const G=window.GUIDE,$=s=>document.querySelector(s);

let mapCategory='guides',mapArea=null;
let saved=new Set();try{const value=JSON.parse(localStorage.getItem('lake-days-saved')||'[]');if(Array.isArray(value))saved=new Set(value.filter(id=>G.places.some(p=>p.id===id)));}catch{}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const region=id=>G.regions.find(r=>r.id===id),byId=id=>G.places.find(p=>p.id===id);
const mapLink=p=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+' '+p.town);
const bookingLink=p=>p.booking?`<a class="booking-link" href="${p.booking}" target="_blank" rel="noopener noreferrer" aria-label="View ${escapeHTML(p.name)} on Booking.com">View on Booking.com ↗</a>`:'';
function placePhotos(p){if(p.pubType&&!MEDIA.photos[p.id])return [];return MEDIA.photos[p.id]||[{...MEDIA.regions[p.area].photo,caption:'Area photograph · '+MEDIA.regions[p.area].label,areaPhoto:true}];}
function photoCard(p){const ph=placePhotos(p)[0];if(!ph)return '<div class="venue-photo-missing">Venue photo not yet verified</div>';return `<figure class="place-photo"><button data-open="${p.id}" aria-label="See photos and details for ${escapeHTML(p.name)}"><img src="${ph.src}" alt="${escapeHTML(ph.areaPhoto?ph.caption:p.name)}" loading="lazy" referrerpolicy="no-referrer"></button><figcaption><a href="${ph.source}" target="_blank" rel="noopener noreferrer">${escapeHTML(ph.areaPhoto?'Area photo · '+MEDIA.regions[p.area].label:ph.credit)} ↗</a></figcaption></figure>`;}
function regionPhoto(id){const ph=MEDIA.regions[id].photo;return `<figure class="feature-photo"><img src="${ph.src}" alt="${escapeHTML(MEDIA.regions[id].featured)}" loading="lazy" referrerpolicy="no-referrer"><figcaption><a href="${ph.source}" target="_blank" rel="noopener noreferrer">${escapeHTML(ph.credit)} ↗</a></figcaption></figure>`;}
function photoGallery(p){if(!placePhotos(p).length)return '<div class="venue-photo-missing">Venue photo not yet verified &middot; see the linked venue source below.</div>';return `<div class="photo-gallery ${placePhotos(p).length===1?'single':''}">${placePhotos(p).map(ph=>`<figure><img src="${ph.src}" alt="${escapeHTML(ph.areaPhoto?ph.caption:p.name)}" referrerpolicy="no-referrer"><figcaption><a href="${ph.source}" target="_blank" rel="noopener noreferrer">${escapeHTML(ph.areaPhoto?ph.caption:ph.credit)} ↗</a></figcaption></figure>`).join('')}</div>`;}
const icons={All:'↗',Beer:'♧',Food:'◒',Explore:'⌁',Swim:'≈',Stay:'⌂',Move:'↔'};
function card(p){return `<article class="card">${photoCard(p)}<div class="card-top"><span class="tag">${icons[p.kind]} ${p.kind} · ${(p.id==='stein'?'Switzerland':region(p.area).country.split(' · ')[0])}</span><button class="heart" data-save="${p.id}" aria-label="${saved.has(p.id)?'Unsave':'Save'} ${escapeHTML(p.name)}" aria-pressed="${saved.has(p.id)}">${saved.has(p.id)?'♥':'♡'}</button></div><div class="card-body"><div class="town">${escapeHTML(p.town)}</div><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.why)}</p>${p.price?`<div class="price">${escapeHTML(p.price)}</div>`:''}${p.kind==='Stay'?`<div class="badge">${p.charging.startsWith('Unknown')||p.charging.startsWith('Not ')?'Bike charging: check with hotel':'Bike charging: source linked'}</div>`:''}${bookingLink(p)}<div class="card-bottom"><button class="detail-btn" data-open="${p.id}">Take a closer look ↗</button><span class="mini">${p.sources.length} source${p.sources.length>1?'s':''}</span></div></div></article>`;}

function persist(){try{localStorage.setItem('lake-days-saved',JSON.stringify([...saved]));}catch{}$('#saved-count').textContent=saved.size;}
function toggleSave(id){saved.has(id)?saved.delete(id):saved.add(id);persist();document.querySelectorAll('[data-save="'+id+'"]').forEach(b=>{b.textContent=saved.has(id)?'♥':'♡';b.setAttribute('aria-pressed',saved.has(id));});const b=$('.save-modal');if(b){b.textContent=saved.has(id)?'♥ Saved':'♡ Save this place';b.setAttribute('aria-pressed',saved.has(id));}}
const rides={
 west:['Konstanz → Mainau','Start at the station, follow the signed cycling route towards Mainau, then park at the entrance and explore the gardens on foot. Return the same way; keep Reichenau for a separate outing rather than squeezing both islands into one day.','About 8–12 km each way · editorial estimate','Konstanz Bahnhof','Mainau Eingang'],
 north:['Meersburg → Unteruhldingen','Start by the harbour and follow the shore towards Unteruhldingen for the Pfahlbauten museum. Return when you feel ready. Visit upper Meersburg on foot afterwards: the castle is above the waterfront. Überlingen is an optional longer outing, not part of this short ride.','About 5–8 km each way · editorial estimate','Meersburg Hafen','Pfahlbauten Unteruhldingen'],
 hops:['Friedrichshafen → Langenargen','Head east from the harbour, through Eriskirch towards Langenargen, following the signed lakeside cycle route. Stop by the water and return along the same corridor. Treat Tettnang and Hopfengut as a separate, hillier inland day; leave the beer tasting until the riding is finished.','Choose an out-and-back distance that suits you','Friedrichshafen Hafen','Langenargen Hafen'],
 lindau:['Lindau → Lochau → Bregenz','Leave the island and follow the lakeside cycle corridor through Lochau to Bregenz. Allow time for busy promenades and stops by the water. Return before settling into Lindau’s pubs, or plan a return without cycling if you stay for drinks.','About 10–15 km each way · editorial estimate','Lindau Insel','Bregenz Hafen'],
 austria:['Bregenz → Lochau → Lindau','Ride north along the lake through Lochau towards Lindau, then park and walk the island lanes. Turn back at Lochau for a shorter outing. Keep the Pfänder panorama as a separate mountain visit rather than adding it to a gentle shore ride.','To Lindau: about 10–15 km each way · editorial estimate','Bregenz Hafen','Lindau Insel'],
 swiss:['Arbon → Rorschach','Follow the Swiss shore from Arbon towards Rorschach, with time for the harbour. Return the same way for a relaxed outing. If the brewery bars are the main event, park the bikes for the evening and arrange a return that does not involve riding. Romanshorn makes a separate ferry-and-harbour excursion.','About 10–15 km each way · editorial estimate','Arbon Schweiz','Rorschach Schweiz']};
const meals={west:'Start around Konstanz’s harbour and old town: Hafenhalle combines food with a beer-garden stop, while Brauhaus Joh. Albrecht is the brewery-table option.',north:'Use Meersburg or Überlingen’s waterfront as your meal stop. In Ueberlingen, the Faulen Pelz offers an inn and beer-garden stop, while Galgenhoelzle is the pub option. Max & Moritz is a farther inland detour.',hops:'Die Speiserei at Hotel Maier is the food-focused option. Hopfengut makes sense on an inland outing. Tettnanger Krone’s traditional restaurant is closed, so do not plan dinner there.',lindau:'Park the bikes and stay on the island: Engel for inn character, Zur Fischerin for a wine-tavern evening, or Wissingers for the old-brewery setting.',austria:'Wirtshaus am See is the checked lakeside inn. Bierbar and Ambiente add town pub options; find them below or in the separate pub guide.',swiss:'Gustav Kahn is the Romanshorn harbour option; Restaurant Löwengarten combines regional food with a former brewery setting in Rorschach.'};
function bind(){if($('#map-filters'))bindMapFilters();if($('#pub-search')){updatePubs();$('#pub-search').oninput=updatePubs;$('#pub-type').onchange=updatePubs;}
 const box=document.querySelector('.atlas-window');
 if(box){let zoom=1;const svg=box.querySelector('svg');const resize=()=>{svg.style.width=(zoom*Math.max(box.clientWidth,box.parentElement.classList.contains('atlas-expanded')?1200:0))+'px';$('#map-zoom-out').disabled=zoom<=1;$('#map-zoom-in').disabled=zoom>=3;};
 $('#map-zoom-in').onclick=()=>{zoom=Math.min(3,zoom+.5);resize();};
 $('#map-zoom-out').onclick=()=>{zoom=Math.max(1,zoom-.5);resize();};
 $('#map-enlarge').onclick=()=>{const open=box.parentElement.classList.toggle('atlas-expanded');document.body.classList.toggle('atlas-open',open);$('#map-enlarge').textContent=open?'Close map':'Enlarge map';$('#map-enlarge').setAttribute('aria-expanded',open);resize();};resize();}
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openPlace(b.dataset.open));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toggleSave(b.dataset.save));}
function rideText(id){const r=rides[id];return '<article class="ride-note"><span class="tag">A DAY BY BIKE</span><h3>'+r[0]+'</h3><p class="distance">'+r[2]+'</p><p>'+r[1]+'</p><p>Check the route, surface and return options before setting off. This is an outing idea, not turn-by-turn navigation.</p><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(r[3])+'&destination='+encodeURIComponent(r[4])+'&travelmode=bicycling">Check cycling directions ↗</a> · <a href="https://www.bodensee-radweg.de/route/etappen/" target="_blank" rel="noopener noreferrer">Lake cycle-route stages ↗</a></article>';}
function section(id,title,places,intro=''){return '<section class="guide-section" id="'+id+'"><h2>'+title+'</h2>'+(intro?'<p class="section-intro">'+intro+'</p>':'')+'<div class="cards">'+places.map(card).join('')+'</div></section>';}
function home(){return '<section class="map-intro"><div><span class="eyebrow">ONE LAKE · SIX LOCAL GUIDES</span><h1>Where shall we go?</h1><p>Tap a place on the map. Find good food, a beer, a bed and a day by bike.</p></div><a class="cycle-link" href="#cycling">◎ Biking around the lake →</a></section><nav class="guide-doorways" aria-label="Lake guides"><a href="#map/bikes"><strong>Find a bike</strong><span>Bike sharing, rentals and where to return them</span></a><a href="#intro"><strong>Get to know Bodensee</strong><span>Geography, history and how the shores fit together</span></a><a href="#pubs"><strong>The pub &amp; beer guide</strong><span>Pubs, brewery bars and beer gardens around the lake</span></a></nav><div class="atlas">'+'<section class="atlas-panel">'+mapFilters()+'<div class="atlas-tools"><button id="map-enlarge" aria-expanded="false">Enlarge map</button><span><button id="map-zoom-out" aria-label="Zoom out">&#8722;</button><button id="map-zoom-in" aria-label="Zoom in">+</button></span></div><div class="atlas-window">'+atlas()+'</div><p class="atlas-help">Zoom in for detail. Swipe to move around the map.</p></section><div id="map-results" tabindex="-1" hidden></div><nav class="six-places" aria-label="Six destination guides">'+G.regions.map((r,i)=>'<a href="#guide/'+r.id+'"><span class="number">'+(i+1)+'</span><span><strong>'+MEDIA.regions[r.id].label+'</strong><small>'+r.tag+'</small></span><b>↗</b></a>').join('')+'</nav></div><p class="map-note">Detailed shoreline overview · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">&copy; OpenStreetMap contributors</a> &middot; Not riding directions.</p>';}
function guide(id){const r=region(id),list=G.places.filter(p=>p.area===id),i=G.regions.indexOf(r);return '<a class="back" href="#">← The six places</a><section class="guide-hero">'+regionPhoto(id)+'<div><span class="eyebrow">GUIDE '+(i+1)+' / 6 · '+r.country+'</span><h1>'+r.name+'</h1><p>'+r.description+'</p></div></section><nav class="chapter-nav" aria-label="In this guide">'+[['eat','Eat & drink'],['see','See & explore'],['bike','By bike'],['stay','Stay']].map(([s,t])=>'<a href="#guide/'+id+'/'+s+'">'+t+'</a>').join('')+'</nav>'+'<p class="area-pubs-link"><a href="#pubs/'+id+'">Open the separate pub guide for this area &rarr;</a></p>'+section('eat','Where to eat & have a beer',list.filter(p=>p.kind==='Beer'||p.kind==='Food'),meals[id])+section('see','In town & around it',list.filter(p=>p.kind==='Explore'||p.kind==='Swim'))+'<section class="guide-section" id="bike"><h2>Explore by bike</h2>'+rideText(id)+'<p><a href="#cycling">Read the general biking guide →</a></p>'+section('rental','Rentals & lake crossings',list.filter(p=>p.kind==='Move'),list.some(p=>p.kind==='Move')?'':'Ask your accommodation about the nearest rental operator and reserve two e-bikes ahead of time. Confirm stock and pickup arrangements directly.')+'</section>'+section('stay','Where to stay',list.filter(p=>p.kind==='Stay'),'Choose your dates on Booking.com for current prices. Bike storage and charging notes are in each hotel’s details.')+'<nav class="end-nav"><a href="#">← Back to the lake</a><a href="#guide/'+G.regions[(i+1)%6].id+'">Next: '+MEDIA.regions[G.regions[(i+1)%6].id].label+' →</a></nav>';}
function cycling(){return '<a class="back" href="#">← The six places</a><article class="cycling"><span class="eyebrow">THE LAKE AT YOUR OWN PACE</span><h1>A good day by bike.</h1><p class="lede">Choose a base, make a small outing, and come back for dinner. You do not need to circle the whole lake to enjoy it.</p>'+regionPhoto('lindau')+'<h2>Start with one shore</h2><p>Each of the six guides includes an outing from that area. Begin with a short out-and-back: you can turn around whenever you like. Leave time for a swim, a museum or a long lunch. The inland hop country and upper towns add climbing; an e-bike helps, but does not make every route effortless.</p><h2>Build your ride in three steps</h2><ol><li>Choose a destination you actually want to visit, then check a cycling route from your accommodation.</li><li>Check the return distance, terrain, weather and battery range. Keep a comfortable reserve and carry the operator’s assistance number.</li><li>Decide how to get home before setting off. If you plan to enjoy beers, finish the cycling first and spend the evening on foot.</li></ol><h2>Renting two e-bikes</h2><p>Reserve two correctly sized bikes, locks and chargers. Confirm pickup and return times, cross-border travel, ferry carriage and breakdown support. Range depends on hills, assistance level and conditions: ask the rental operator about your actual route.</p><div class="link-list"><button data-open="kultur">Konstanz rental ↗</button><button data-open="bregenzrental">Bregenz rental ↗</button><button data-open="rentaswiss">Swiss rental finder ↗</button></div><h2>Use the lake as a shortcut</h2><p>The Konstanz–Meersburg and Friedrichshafen–Romanshorn ferries carry bikes. Check the operator’s current sailing times, fares and final return. The Konstanz–Friedrichshafen catamaran has limited bike space; do not depend on boarding with both bikes for a tight connection.</p><div class="link-list"><button data-open="staadferry">Meersburg ferry ↗</button><button data-open="romanferry">Romanshorn ferry ↗</button><button data-open="kat">Catamaran ↗</button></div><h2>At the hotel</h2><p>Confirm secure space for both bikes and permission to charge with your supplied chargers. Covered parking does not necessarily mean locked storage. The hotel details distinguish confirmed facilities from questions still to ask.</p><h2>On the way</h2><p>Follow signed cycling routes, slow down around walkers and dismount where required. Carry water, rain protection, a charged phone and an offline copy of your chosen route. Our illustrated map is for choosing an area, not navigation.</p><p><a href="https://www.bodensee-radweg.de/route/etappen/" target="_blank" rel="noopener noreferrer">Explore the Bodensee cycle-route stages ↗</a></p><a class="back" href="#">Choose one of the six places →</a></article>';}
function render(){document.body.classList.remove('atlas-open');const parts=location.hash.slice(1).split('/');if(parts[0]==='map'&&parts[1]==='bikes'){mapCategory='bikes';mapArea=null;}const id=parts[0]==='guide'&&region(parts[1])?parts[1]:null;const key=id?'guide/'+id:parts[0];if(render.key!==key){$('#screen').innerHTML=id?guide(id):key==='pubs'?pubGuide():key==='intro'?introduction():key==='cycling'?cycling():key==='saved'?'<a class="back" href="#">← The six places</a><h1>Your saved places</h1><div class="cards">'+(G.places.filter(p=>saved.has(p.id)).map(card).join('')||'<p>Tap a heart inside a guide to save a place here.</p>')+'</div>':home();render.key=key;bind();window.scrollTo(0,0);}if(key==='map'&&parts[1]==='bikes'){$('#map-filters')?.scrollIntoView();}if(key==='intro'&&parts[1])document.getElementById(parts[1])?.scrollIntoView();if(key==='pubs'&&parts[1])document.getElementById('pub-'+parts[1])?.scrollIntoView();if(id&&parts[2])document.getElementById(parts[2])?.scrollIntoView();persist();}
$('#saved-top').onclick=()=>{location.hash='saved';};window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.atlas-expanded'))document.querySelector('#map-enlarge').click();});
function openPlace(id){const p=byId(id);$('#detail-content').innerHTML=`${photoGallery(p)}<div class="tag">${p.kind} · ${escapeHTML(p.town)}</div><h2>${escapeHTML(p.name)}</h2>${p.price?`<div class="price">${escapeHTML(p.price)}</div>`:''}<p>${escapeHTML(p.why)}</p><h3>${p.kind==='Stay'?'Your evenings':'What to try / do'}</h3><p>${escapeHTML(p.try)}</p><h3>Nearby possibilities</h3><p>${escapeHTML(p.near)}</p>${p.storage?`<h3>Bike storage</h3><p>${escapeHTML(p.storage)}</p><h3>E-bike charging</h3><p>${escapeHTML(p.charging)}</p><h3>Rental access</h3><p>${escapeHTML(p.rental)}</p>`:''}<div class="notice">${escapeHTML(p.note)}</div><h3>Checked sources · ${G.checked}</h3><div class="source-links">${p.sources.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)} ↗</a>`).join('')}</div>${p.booking?`<h3>Compare rooms</h3>${bookingLink(p)}<p>Choose your dates on Booking.com for current prices and availability.</p>`:''}<div class="modal-actions"><a href="${mapLink(p)}" target="_blank" rel="noopener noreferrer">Find on a street map ↗</a><button class="pill save-modal" aria-pressed="${saved.has(id)}">${saved.has(id)?'♥ Saved':'♡ Save this place'}</button></div>`;$('#detail .save-modal').onclick=()=>toggleSave(id);if(!$('#detail').open)$('#detail').showModal();}
$('.dialog-close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#export').onclick=()=>{const list=G.places.filter(p=>saved.has(p.id));if(!list.length){$('#status').textContent='Save a few places with the hearts first.';return;}const out=['LAKE DAYS — SAVED PLACES','Sources checked '+G.checked,'Saved from this browser; no bookings or itinerary.','',...list.map(p=>[p.name+' — '+p.town,p.why,'Try: '+p.try,'Nearby: '+p.near,p.price||'',p.storage?'Storage: '+p.storage:'',p.charging?'Charging: '+p.charging:'',p.rental?'Rental: '+p.rental:'','Check: '+p.note,p.booking?'Booking.com: '+p.booking:'',...p.sources.map(([n,u])=>n+': '+u),''].filter(Boolean).join('\n'))].join('\n\n');const url=URL.createObjectURL(new Blob([out],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='lake-days-saved-places.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#status').textContent='Saved-place list exported.';};
